require __DIR__.'/common.php'; $method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET') { require_user(); if(($_SESSION['role']??'')==='admin'){$s=$pdo->query('SELECT o.id,o.user_id,u.username,o.items_json,o.total,o.status,o.created_at FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC');}else{$s=$pdo->prepare('SELECT id,user_id,items_json,total,status,created_at FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([$_SESSION['user_id']]);} respond(['orders'=>$s->fetchAll()]); }
if($method==='POST') { require_user();$d=json_input();$items=$d['items']??[];if(!is_array($items)||!count($items))respond(['error'=>'Keranjang kosong'],422);try{$pdo->beginTransaction();$safe=[];$total=0;foreach($items as $item){$id=(int)($item['id']??0);$qty=(int)($item['quantity']??1);if($id<1||$qty<1||$qty>99)throw new RuntimeException('Item pesanan tidak valid');$s=$pdo->prepare('SELECT id,name,price,stock,image FROM products WHERE id=? FOR UPDATE');$s->execute([$id]);$p=$s->fetch();if(!$p||$p['stock']<$qty)throw new RuntimeException('Stok tidak cukup untuk '.($p['name']??'produk'));$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$id]);$line=(float)$p['price']*$qty;$total+=$line;$safe[]=['id'=>$id,'name'=>$p['name'],'price'=>(float)$p['price'],'quantity'=>$qty,'image'=>$p['image']];}$s=$pdo->prepare('INSERT INTO orders(user_id,items_json,total,status) VALUES(?,?,?,\'pending\')');$s->execute([$_SESSION['user_id'],json_encode($safe,JSON_UNESCAPED_UNICODE),$total]);$id=(int)$pdo->lastInsertId();$pdo->commit();respond(['ok'=>true,'order_id'=>$id,'total'=>$total],201);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();respond(['error'=>$e instanceof RuntimeException?$e->getMessage():'Pesanan gagal diproses'],422);} }
if($method==='PATCH') {require_admin();$d=json_input();$status=$d['status']??'';if(!in_array($status,['pending','paid','processing','shipped','completed','cancelled'],true))respond(['error'=>'Status tidak valid'],422);$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,(int)($d['id']??0)]);respond(['ok'=>true]);}
